using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;

namespace PaymentAuthorization.ArchitectureTest;

/// <summary>Guards the dependency rule: Domain and Application must not reach technical details.</summary>
public class LayerDependencyTests
{
    private const string Domain = "PaymentAuthorization.Domain";
    private const string Application = "PaymentAuthorization.Application";
    private const string Infrastructure = "PaymentAuthorization.Infrastructure";

    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process",
        "Microsoft.Data", "Microsoft.EntityFrameworkCore", "Microsoft.AspNetCore",
        "Microsoft.Extensions.Http", "Newtonsoft",
    ];

    [Fact]
    public void Domain_depends_on_no_other_layer()
        => AssertNoReferences(Domain, [Application, Infrastructure]);

    [Fact]
    public void Application_does_not_depend_on_Infrastructure()
        => AssertNoReferences(Application, [Infrastructure]);

    [Theory]
    [InlineData(Domain)]
    [InlineData(Application)]
    public void Business_layers_do_not_use_technical_namespaces(string layer)
    {
        var used = ReadReferences(layer).TypeNamespaces
            .Where(ns => TechnicalNamespaces.Any(t => ns == t || ns.StartsWith(t + ".")))
            .Distinct().Order().ToList();

        Assert.True(used.Count == 0, $"{layer} uses technical namespaces: {string.Join(", ", used)}");
    }

    private static void AssertNoReferences(string layer, string[] forbidden)
    {
        var offending = ReadReferences(layer).Assemblies.Where(forbidden.Contains).ToList();
        Assert.True(offending.Count == 0, $"{layer} references: {string.Join(", ", offending)}");
    }

    private static (List<string> Assemblies, List<string> TypeNamespaces) ReadReferences(string assemblyName)
    {
        using var stream = File.OpenRead(Assembly.Load(assemblyName).Location);
        using var pe = new PEReader(stream);
        var md = pe.GetMetadataReader();
        var assemblies = md.AssemblyReferences.Select(h => md.GetString(md.GetAssemblyReference(h).Name)).ToList();
        var namespaces = md.TypeReferences
            .Select(h => md.GetString(md.GetTypeReference(h).Namespace)).ToList();
        return (assemblies, namespaces);
    }
}
